function minImpossibleOR(nums) {
  let present = 0;
  for (const num of nums) {
    if ((num & (num - 1)) === 0) {
      present |= num;
    }
  }
  let answer = 1;
  while ((present & answer) !== 0) {
    answer <<= 1;
  }
  return answer;
}

