function minImpossibleOR(nums) {
  // Collect the OR of every non-empty choice of elements, one element at a time.
  let reachable = new Set();
  for (const num of nums) {
    const next = new Set(reachable);
    next.add(num);
    for (const value of reachable) next.add(value | num);
    reachable = next;
  }
  let x = 1;
  while (reachable.has(x)) x++;
  return x;
}

