function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 8);
    // Often start with a run of the smallest powers of two so that larger answers appear.
    const nums = [];
    const run = rand() < 0.6 ? pick(1, 5) : 0;
    for (let bit = 0; bit < run && nums.length < n; bit++) nums.push(1 << bit);
    while (nums.length < n) {
      const roll = rand();
      if (roll < 0.4) nums.push(1 << pick(0, 5));
      else if (roll < 0.9) nums.push(pick(1, 40));
      else nums.push(pick(1, 1000000000));
    }
    for (let i = nums.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
    return [nums];
  }
  const n = rand() < 0.5 ? 2000 : pick(30, 2000);
  const shape = rand();
  // Every power of two below 2^top appears, plus filler that never contains 2^top on its own.
  const top = shape < 0.3 ? 30 : pick(0, 29);
  const nums = [];
  for (let bit = 0; bit < top; bit++) nums.push(2 ** bit);
  while (nums.length < n) {
    const value = pick(1, 1000000000);
    if (value !== 2 ** top) nums.push(value);
  }
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
